      return false;
    },
    programs: () => g.engine.renderer.info.programs.length,
    batches: () => { const own = new Set(); for (const x of W.storyGroups.values()) for (const o of x.objects) o.traverse((m) => own.add(m)); let n = 0; W.root.traverse((o) => { if (o.isMesh && !own.has(o) && vis(o)) n++; }); return n; },
    flames: () => { let n = 0; let on = 0; W.root.traverse((o) => { if (o.isMesh && /^flame:/.test(o.name)) { n++; if (vis(o)) on++; } }); return `${on}/${n}`; },
