    shoreDiff: () => {
      const w = W.water; const R = w.resolution;
      const full = bakeShore(w.shoreInput(), 0, 0, W.tileMap.width * R, W.tileMap.depth * R);
      let d = 0; for (let k = 0; k < full.length; k++) if (full[k] !== w._shoreData[k]) d++;
      return d;
    },
    applied: [],
    state: () => ({ flames: SP.flames(), fires: W.fires.length, audioFires: g.audioDirector.fires === W.fires ? W.fires.length : -1, markers: SP.markers(), shoreDiff: SP.shoreDiff(), colliders: W.tileMap.colliders.length, programs: SP.programs() }),
