      SP.expect(SP.batches() === SP.b0, `${name}=${v}: the merged batches stay (a group collapses its ranges, STORY-03)`);
      return a;
    },
  };
  const orig = W.applyStory.bind(W);
  W.applyStory = (o) => { const t0 = performance.now(); const r = orig(o); SP.applied.push({ ms: +(performance.now() - t0).toFixed(1), changed: r.changed.length, mapChanged: r.mapChanged }); return r; };
