})()

(async () => {
  const { g, sleep } = window.SP;
  const r = g.engine.renderer;
  const L = g.lighting;
  const C = L.fog.color.constructor;
  const read = () => { const c = new C(); r.getClearColor(c); return { clear: c.getHexString(), fog: L.fog.color.getHexString(), sky: L.sky.object.visible }; };
  const before = read();
  L.settings.backdrop = new C(0xff0000);
  await sleep(150);
  const red = read();
  L.settings.backdrop = new C(0x0000ff);
  await sleep(150);
  const blue = read();
  L.settings.backdrop.setHex(0x00ff00);
  await sleep(150);
  const green = read();
  L.settings.backdrop = null;
  await sleep(150);
  const after = read();
  SP.expect(red.clear === 'ff0000' && !red.sky, 'backdrop: the clear colour and no sky');
  SP.expect(blue.clear === '0000ff' && blue.fog === '0000ff', 'backdrop replaced: the clear colour follows');
  SP.expect(green.clear === '00ff00', 'backdrop changed in place: the clear colour follows');
  SP.expect(after.clear === before.clear && after.sky, 'no backdrop: the clear colour and the sky back');
  return JSON.stringify({ before, red, blue, green, after, failed: SP.failed });
})()

(async () => {
  const { W, sleep } = window.SP;
  const P = W.lightPool;
  const orig = P.descriptors.slice();
  const d = orig[0];
  const h = () => P.handles.find((x) => x.desc === d);
  P.setHidden(d, true, { instant: true });
  P.setDescriptors(P.descriptors);
  await sleep(100);
  const same = { fade: h()?.fade, intensity: h()?.light.intensity };
  P.setDescriptors(P.descriptors.slice(), { snap: true });
  await sleep(100);
  const snap = { fade: h()?.fade, intensity: h()?.light.intensity };
  P.setDescriptors(orig.filter((x) => x !== d));
  const forgotten = !P.isHidden(d);
  P.setDescriptors(orig);
  await sleep(600);
  const back = { fade: h()?.fade, intensity: h()?.light.intensity };
  SP.expect(same.fade === 0 && same.intensity === 0, 'setDescriptors (same set): a hidden lamp stays dark');
  SP.expect(snap.fade === 0 && snap.intensity === 0, 'setDescriptors (snap): a hidden lamp stays dark');
  SP.expect(forgotten, 'setDescriptors: a hidden descriptor that left the set is forgotten');
